//! Same descriptor for models, human manual and Argus/diagnostic adapters.

pub const DESCRIPTOR: &str = r#"{"owner":"STUDIO-MODULE-INTEROP_LAYOUT","version":1,"operation":"open_idml(bytes, Limits, CancellationToken) -> IdmlPackage (every part kept with sha256); decode_idml / import_idml(bytes, Limits, IdMint, CancellationToken) -> IdmlImport {package, model, proposal {Folio snapshot, StudioTextStory per story, style refs, ids}, loss}; replace_content(package, ContentEdit, Limits, token) -> IdmlPackage; write_idml(package) -> bytes; export_idml(import, token) -> bytes; reflow_import(import, ParagraphShaper, ReflowOptions, token) -> ThreadReflow[] (hsk-studio-layout placement + overset span per frame chain, or a typed layout refusal); export_folio(FolioExportInput {Folio StudioDocument, StudioTextStory inputs, ExportNames}, Limits, token) -> FolioExport {IDML bytes, typed model, loss}; IdmlImport::export_names(); identify_indd(bytes) -> IndKind; import_indd(bytes, Limits, token) -> always Err","operator":{"intent":"Bring an InDesign IDML package into a Studio layout document as page spreads, pages, threaded text frames and text stories without silent loss, edit story text, and write IDML back","result":"A proposal (nothing is committed) plus a typed loss list naming every part, element and attribute family that was not interpreted, approximated or dropped","recovery":"zip_invalid / unsafe_entry_name / duplicate_entry / mimetype_invalid: the file is not a safe IDML container, re-export it from InDesign; entity_denied: remove the DOCTYPE; budget_exceeded: raise the named Limits field only for a trusted file; dangling_story / thread_not_reciprocal / cyclic_thread: the frame links are corrupt; stale_source: re-decode and re-read the span; native_editability_blocked: keep the original .indd, export IDML from InDesign and import that; canceled: nothing was produced"},"model":{"container":"ZIP; mimetype first and stored with the exact IDML string; STORE and DEFLATE only; no ZIP64, encryption or multi-disk; names must be relative without .., backslash, drive colon or control characters; exact and case-folded duplicates rejected; local header must match the central directory; overlapping entry data refused; CRC-32 verified","units":"IDML geometry is points (Unit::Points, no conversion); page GeometricBounds are top left bottom right in page coordinates; page and frame ItemTransform are affine [a b c d tx ty]; frame bounds are the bounding box of the path anchors under ItemTransform, converted to the coordinates of the page with the largest overlap","folio":"one StudioPageSpread per Spread (name = page names joined), one StudioPage per Page (side from FacingPages and spine position, margins from the page MarginPreference or the document MarginPreference, bleed from DocumentPreference), one text layer with text_frame per TextFrame (columns, gutter, inset, vertical justification, first baseline, auto size from TextFramePreference), previous/next thread links rebuilt from the validated chain, one StudioTextStory per Story (paragraph and character ranges, applied styles as STYS ids that Folio reports unresolved because style definitions stay in Resources/Styles.xml, applied language as a sanitized key)","text":"story text = Content text; a Br ends the paragraph and contributes one newline; special-character processing instructions are dropped and reported","threads":"previous/next must be reciprocal and acyclic (typed errors); a link to a frame outside the supported subset ends the chain there and is reported; a second chain of the same story is not projected and is reported","reflow":"every story with a Folio frame chain is composed by hsk-studio-layout (first-fit or Knuth-Plass, one column, top-aligned fixed-size frames, left-to-right Latin); shaping is a host port (ParagraphShaper; FixedAdvanceShaper is a fixture, not shaping) because IDML names fonts and does not carry them; an RTL/CJK/vertical/complex-script story (reflow_certified false) is refused as unsupported_composition before shaping; layout refusals (multi-column, vertical justification, auto size, cap height/em box/x-height first baseline, missing_font, ...) are returned per thread and never hide other threads; overset is the first unplaced story byte through the end of the story; AscentOffset/LeadingOffset/FixedHeight first baselines are mapped to layout fixed offset inset_top + max(min, metric of the first shaped paragraph) and reported as first_baseline_mapped_to_fixed (UNVERIFIED against InDesign)","folio_export":"the Folio document is validated first; pages are placed with the spine at the origin for facing pages and at the spread centre otherwise, frames are written as rectangular paths with TextFramePreference, stories as paragraph/character ranges with Br paragraph ends; style and language references are written through ExportNames (unmapped = built-in no-style, reported); artboards, non-text layers, layer appearance, sequences, per-page bleed differences and single-sided pages in a facing document are reported; ids are minted deterministically (us1, up1, uf1, ua1); the package shape and DOMVersion 16.0 are UNVERIFIED against InDesign","groups":"text frames inside Group elements (any depth) are not decoded (group transforms are not composed) and are counted as preserved_opaque text_frame_in_group_not_decoded; the group stays verbatim; links to such frames end the chain and are reported as thread_link_outside_subset","preservation":"every package part is kept verbatim with its sha256; unrecognised spread and designmap children, page and frame children, story head children and Properties elements are kept as verbatim XML text in the model; export_idml writes them back, replace_content/write_idml never touch them","composition":"RTL direction or language, CJK language or typography, vertical text and complex-script languages are reported as unsupported_composition on the story and reflow_certified is false: a Latin reflow must not be run on such a story (the language lists are a heuristic, UNVERIFIED for completeness)"},"loss":{"kinds":"preserved_opaque (not interpreted, kept by every write path), unsupported (not interpreted, dropped by export_idml, kept by replace_content/write_idml), approximated (frame off page, rotated transform, curved path, defaulted margins, colour mode assumed RGB, link outside subset, unknown preference value), unsupported_composition","examples":"graphic_page_item_not_interpreted, group_not_descended and text_frame_in_group_not_decoded (frames inside groups are not decoded), part_preserved_verbatim (styles, graphics, fonts, master spreads, XML structure), paragraph_range_element_not_interpreted (tables, footnotes), special_character_dropped"},"limits":{"max_bytes":134217728,"max_entries":4096,"max_entry_bytes":67108864,"max_inflated_bytes":268435456,"max_ratio":100,"xml_nodes":1000000,"folio_nodes":100000,"case_seconds":60},"safety":"roxmltree with DTDs disabled (any DOCTYPE is refused, so no entity is ever declared or expanded); no external reference, file, network or process access exists in this crate; parts must be UTF-8","cancel":"CancellationToken is checked at entry and per entry, part, element group and story; a canceled call returns canceled and no partial result","undo":"imports are proposals only; the host records an applied revision as one reversible step; replace_content returns a new package and never mutates the input","indd":"identify_indd checks the 16-byte InDesign GUID, the 8-byte type string (DOCUMENT, BOOKBOOK, LIBRARY4), the endianness byte and the version (public registry PRONOM fmt/548, fmt/1191, fmt/1192; UNVERIFIED on an InDesign-saved file, none exists on this machine); import_indd returns NativeEditabilityBlocked with the original bytes preserved and its Ok type is uninhabited: INDD is never claimed readable and an IDML package never satisfies it (STU-IO-186)","argus":{"inspect":"IdmlImport.proposal, model and loss","action":"the same functions with the same cancellation token","capture":"caller captures the source bytes, the proposal and the Observe frame under a fresh grant"},"diagnostics":"report() emits one Observe terminal outcome; no ids, part names or text are serialized by this crate","next":"Type-backed ParagraphShaper with IDML style-to-font resolution, text wrap obstacles, decoding frames inside groups with composed transforms, Chronicle patch write-back of edits, styles and swatches (Resources), master spreads, tables, footnotes, anchored objects, frames inside groups, EPUB and PDF-X"}"#;
